<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= esc($title ?? 'Asset Management') ?></title>
<style>
:root{--navy:#152d4d;--blue:#2563eb;--bg:#f4f7fb;--line:#dbe3ee;--muted:#64748b;--danger:#dc2626}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#172b4d;font:14px/1.45 Inter,Segoe UI,Arial,sans-serif}header{background:var(--navy);color:white;padding:14px 26px;display:flex;justify-content:space-between;align-items:center}header a{color:white;text-decoration:none;margin-left:15px}.container{max-width:1500px;margin:26px auto;padding:0 20px}.panel{background:white;border:1px solid var(--line);border-radius:12px;padding:20px;box-shadow:0 5px 18px #142d4d08}.cards{display:grid;grid-template-columns:repeat(7,minmax(100px,1fr));gap:12px;margin-bottom:18px}.stat{background:white;border:1px solid var(--line);border-radius:10px;padding:15px}.stat small{color:var(--muted)}.stat strong{display:block;font-size:24px;margin-top:7px}h1{font-size:23px;margin:0 0 18px}h2{font-size:18px}.btn{display:inline-block;border:0;border-radius:7px;padding:9px 13px;text-decoration:none;background:var(--blue);color:white;cursor:pointer;font-weight:600}.btn.gray{background:#64748b}.btn.red{background:#dc2626}.btn.green{background:#15803d}.toolbar{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.toolbar input,.toolbar select,input,select{padding:9px 10px;border:1px solid #cbd5e1;border-radius:6px;max-width:100%}label{display:block;font-weight:600;margin-bottom:5px} .field{min-width:0}.field input,.field select{width:100%}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.required{color:#dc2626}.muted{color:var(--muted)}.error{color:#b91c1c;font-size:12px}.flash{padding:12px;border-radius:7px;margin-bottom:14px;background:#dcfce7;color:#166534}.flash.err{background:#fee2e2;color:#991b1b}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #e5eaf1;text-align:left;padding:11px 9px;white-space:nowrap}th{background:#f8fafc;color:#475569}th a{color:inherit;text-decoration:none}.table-wrap{overflow:auto}.badge{border-radius:99px;padding:4px 8px;font-size:11px;font-weight:700;background:#e2e8f0}.badge.Active{background:#dcfce7;color:#166534}.badge.Idle{background:#fef3c7;color:#92400e}.badge.Maintenance{background:#ffedd5;color:#9a3412}.badge.Scrap{background:#fee2e2;color:#991b1b}.pagination{display:flex;justify-content:space-between;align-items:center;margin-top:15px}.pagination a{padding:7px 10px;border:1px solid var(--line);border-radius:5px;text-decoration:none;color:var(--navy)}.auth{max-width:440px;margin:8vh auto}.auth .field{margin:14px 0}.actions{display:flex;gap:6px}.hint{font-size:12px;color:var(--muted)}@media(max-width:1000px){.cards{grid-template-columns:repeat(3,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.grid4{grid-template-columns:1fr}.cards{grid-template-columns:repeat(2,1fr)}header{padding:12px;display:block}header nav{margin-top:10px}}
